package com.vandorlabs.client;
import com.google.gson.*;
import com.vandorlabs.programmer.*;
import net.minecraft.util.EnumFacing;
import net.minecraft.util.math.*;
import java.nio.file.*;
import java.io.*;
/** Calls the released authored triangle picker independently for every reserved cell. */
public final class ProgrammerRaysLegacyChecks {
 private static final Gson JSON=new Gson();
 private static JsonArray point(Vec3d value){JsonArray result=new JsonArray();result.add(value.x);result.add(value.y);result.add(value.z);return result;}
 private static Vec3d world(ProgrammerTransform.Affine a,BlockPos origin,double x,double y,double z){return new Vec3d(origin.getX()+a.x(x,z),origin.getY()+y,origin.getZ()+a.z(x,z));}
 public static void main(String[] args)throws Exception{Path output=Paths.get(System.getProperty("vandorlabs.programmerRaysReference","build/test-artifacts/programmer-rays-forge.jsonl"));Files.createDirectories(output.toAbsolutePath().getParent());java.security.MessageDigest hash=java.security.MessageDigest.getInstance("SHA-256");int cases=0,hits=0;int[] slots=new int[5];BlockPos root=new BlockPos(7,80,-11);try(Writer writer=Files.newBufferedWriter(output)){for(EnumFacing facing:EnumFacing.HORIZONTALS){BlockPos origin=facing==EnumFacing.SOUTH?root.west():facing==EnumFacing.WEST?root.north():root;ProgrammerTransform.Affine a=ProgrammerGeometry.transform(facing);for(int part=0;part<4;part++)for(int axis=0;axis<3;axis++)for(int sign=0;sign<2;sign++)for(int u=0;u<=16;u++)for(int v=0;v<=16;v++){double[] from=new double[3],to=new double[3];int first=(axis+1)%3,second=(axis+2)%3;double[] size={2,2,1};from[axis]=sign==0?-1:size[axis]+1;to[axis]=sign==0?size[axis]+1:-1;from[first]=to[first]=-.125+(size[first]+.25)*u/16;from[second]=to[second]=-.125+(size[second]+.25)*v/16;Vec3d start=world(a,origin,from[0],from[1],from[2]),end=world(a,origin,to[0],to[1],to[2]);BlockPos cell=ProgrammerBlock.cell(root,facing,part);RayTraceResult hit=ProgrammerGeometry.trace(cell,origin,facing,start,end);JsonObject row=new JsonObject();row.addProperty("facing",facing.name());row.addProperty("part",part);row.add("from",point(start));row.add("to",point(end));if(hit!=null){row.add("hit",point(hit.hitVec));row.addProperty("side",hit.sideHit.name());row.addProperty("slot",hit.subHit);row.addProperty("group",String.valueOf(hit.hitInfo));hits++;slots[hit.subHit+1]++;}String line=JSON.toJson(row)+"\n";hash.update(line.getBytes(java.nio.charset.StandardCharsets.UTF_8));writer.write(line);cases++;} }StringBuilder golden=new StringBuilder();for(byte value:hash.digest())golden.append(String.format(java.util.Locale.ROOT,"%02x",value&255));if(cases!=27744||hits!=7280||!golden.toString().equals("0aaef112119fe6e8f5f72e5462843a3d4af766426f35055a143dc93fd4a8ce54"))throw new AssertionError("Released Programmer authored rays changed: "+golden);JsonObject summary=new JsonObject();summary.addProperty("cases",cases);summary.addProperty("hits",hits);summary.addProperty("golden",golden.toString());writer.write(JSON.toJson(summary)+"\n");System.out.println("Actual Programmer triangle rays Source PASS cases="+cases+" hits="+hits+" slots="+java.util.Arrays.toString(slots)+" golden="+golden);}}
}
